public static long findNthGoodInteger(long N) {
    long count = 0;
    long current = 0;

    while (count < N) {
        current++;
        if (isGoodInteger(current)) {
            count++;
        }
    }

    return current;
}

private static boolean isGoodInteger(long num) {
    while (num > 0) {
        long digit = num % 10;
        if (digit != 0 && digit != 2 && digit != 4 && digit != 6 && digit != 8) {
            return false;
        }
        num /= 10;
    }
    return true;
}
